{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C01", "C02", "C04", "C11", "C13", "C76"],
  "contradictory_card_ids": ["C22"],
  "prediction_basis_card_ids": ["C01", "C04", "C11", "C13", "C76"],
  "claims": [
    {
      "claim": "Pramipexole, a small basic secondary amine that is fully ionized at physiological pH, has accepted oral bioavailability above 90% (C01), and L3 shows measurable steady-state oral exposure after extended-release dosing (C76), supporting that ionization does not preclude F≥20%.",
      "card_ids": ["C01", "C76"]
    },
    {
      "claim": "5-Hydroxytryptophan, an ionized indole amino acid, has mean absolute oral bioavailability of 49% in humans (C11), and labetalol, a basic carboxamide-containing amine, has 33% F in controls and 63% in cirrhosis (C13, C16, C17, C24), both above threshold.",
      "card_ids": ["C11", "C13", "C16", "C17", "C24"]
    },
    {
      "claim": "AZD0837, a basic amidine prodrug, has absolute oral bioavailability of 22-55% (C04, C05, C14, C20), providing a supportive reference range at or above the 20% threshold.",
      "card_ids": ["C04", "C05", "C14", "C20"]
    },
    {
      "claim": "Ebastine has a measured oral bioavailability of about 40% (C02), and PF-05241328 has 38% absolute F (C03, C08), both above threshold despite qualitative 'low/poor' descriptors elsewhere.",
      "card_ids": ["C02", "C03", "C08"]
    },
    {
      "claim": "The only below-threshold measured F among the reference contexts is isradipine's non-cirrhotic baseline of 16% (C22), but it is condition-specific and structurally dissimilar (dihydropyridine ester), so it does not transfer to the query.",
      "card_ids": ["C22"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "low",
      "direction": "supportive",
      "decision_effect": "no_change",
      "card_ids": ["C76"]
    }
  ],
  "evidence_gaps": [
    "No direct measured oral bioavailability for the query molecule; prediction relies on transfer from reference contexts.",
    "L3 records are oral exposure measurements for other molecules and lack IV comparators for the query; none directly establish F.",
    "Pramipexole Tmax (C76) confirms oral absorption but not F magnitude.",
    "First-pass metabolism and transporter-mediated absorption for the query are not directly assessed.",
    "The isradipine non-cirrhotic baseline F of 16% is below threshold but condition-specific and structurally dissimilar."
  ],
  "decision_summary": "L3 oral AUC/Cmax records do not provide direct F for the query; the closest reference (pramipexole) shows oral absorption consistent with its accepted >90% F, and no L3 record supplies affirmative threshold-relevant evidence for F<20%. The high prediction is retained with moderate confidence."
}

